// Raw-CUDA implementation of the gate mini-step: the speed-of-light reference.
// Mirrors bench/microbench/warp_bench.py line for line, including the draw order.
// Tables come from tables.h, generated by tables.py, so the two cannot drift.
#include <cstdio>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <cuda_runtime.h>
#include "tables.h"

#define NSTATS 5
#define HP_SCALE 8
#define SEED_KEY 0x9E3779B9u
#define CK(x) do { cudaError_t e = (x); if (e) { printf("{\"error\":\"%s\"}\n", cudaGetErrorString(e)); exit(1); } } while (0)

struct St {
    int *hp, *maxhp, *status, *toxctr, *level;  // [B][2]
    int *stats, *boosts;                        // [B][2][NSTATS]
    int *types;                                 // [B][2][2]
    int *mvs;                                   // [B][2][4]
    int *ctr, *gen, *result;                    // [B]
};

__device__ __forceinline__ uint32_t mix(uint32_t x) {
    x ^= x >> 16; x *= 0x7FEB352Du; x ^= x >> 15; x *= 0x846CA68Bu; x ^= x >> 16;
    return x;
}
__device__ __forceinline__ uint32_t draw(int lane, int gen, int c) {
    uint32_t k = mix((uint32_t)lane ^ SEED_KEY) ^ mix((uint32_t)gen * 2654435761u);
    return mix(k ^ mix((uint32_t)c));
}
__device__ __forceinline__ int rand_n(uint32_t v, int n) {
    return (int)(((uint64_t)v * (uint64_t)n) >> 32);
}
__device__ __forceinline__ int boosted(int stat, int stage) {
    return stage >= 0 ? stat * (2 + stage) / 2 : stat * 2 / (2 - stage);
}

__device__ void init_lane(St s, int lane, int gen) {
    for (int side = 0; side < 2; side++) {
        int b = lane * 2 + side;
        uint32_t h = mix((uint32_t)(lane * 2 + side) ^ mix((uint32_t)gen ^ SEED_KEY));
        s.level[b] = 70 + rand_n(mix(h ^ 1u), 31);
        int mx = (200 + rand_n(mix(h ^ 2u), 200)) * HP_SCALE;
        s.maxhp[b] = mx; s.hp[b] = mx;
        for (int j = 0; j < NSTATS; j++) {
            s.stats[b * NSTATS + j] = 120 + rand_n(mix(h ^ (uint32_t)(10 + j)), 260);
            s.boosts[b * NSTATS + j] = 0;
        }
        int t0 = rand_n(mix(h ^ 3u), 17);
        s.types[b * 2 + 0] = t0;
        s.types[b * 2 + 1] = (t0 + 1 + rand_n(mix(h ^ 4u), 16)) % 17;
        for (int j = 0; j < 4; j++) s.mvs[b * 4 + j] = rand_n(mix(h ^ (uint32_t)(20 + j)), 20);
        s.status[b] = 0; s.toxctr[b] = 0;
    }
    s.ctr[lane] = 0; s.gen[lane] = gen; s.result[lane] = 0;
}

__device__ int type_mod(St s, int mtype, int lane, int dfn) {
    int b = lane * 2 + dfn;
    int m = CHART[mtype][s.types[b * 2 + 0]];
    int t1 = s.types[b * 2 + 1];
    if (t1 != s.types[b * 2 + 0]) m += CHART[mtype][t1];
    return m;
}

__device__ int one_hit(St s, int lane, int att, int dfn, int mi, int c) {
    int A = lane * 2 + att, D = lane * 2 + dfn;
    int power = MOVES[mi][2], cat = MOVES[mi][1], mtype = MOVES[mi][0];
    int ai = cat == 1 ? 2 : 0, di = cat == 1 ? 3 : 1;
    int a = boosted(s.stats[A * NSTATS + ai], s.boosts[A * NSTATS + ai]);
    int d = boosted(s.stats[D * NSTATS + di], s.boosts[D * NSTATS + di]);
    if (s.status[A] == 4 && cat == 0) a /= 2;
    int dmg = ((2 * s.level[A] / 5 + 2) * power * a / d) / 50 + 2;
    if (rand_n(draw(lane, s.gen[lane], c), 16) < 1) dmg *= 2;
    if (mtype == s.types[A * 2 + 0] || mtype == s.types[A * 2 + 1]) dmg = dmg * 3 / 2;
    int tm = type_mod(s, mtype, lane, dfn);
    if (tm < -6) return 0;
    for (int k = 0; k < tm; k++) dmg *= 2;
    for (int k = 0; k < -tm; k++) dmg /= 2;
    int r = rand_n(draw(lane, s.gen[lane], c + 1), 16);
    dmg = dmg * (100 - r) / 100;
    return dmg > 1 ? dmg : 1;
}

// Returns the new counter packed with the flinch flag: c * 2 + flinched.
__device__ int use_move(St s, int lane, int att, int dfn, int act, int c) {
    int A = lane * 2 + att, D = lane * 2 + dfn;
    int mi = s.mvs[A * 4 + act];
    int fam = MOVES[mi][4], acc = MOVES[mi][3], p0 = MOVES[mi][5], p1 = MOVES[mi][6];
    if (acc != NEVER_MISS) {
        if (rand_n(draw(lane, s.gen[lane], c), 100) >= acc) return (c + 1) * 2;
        c += 1;
    }
    if (fam == 4) {
        for (int j = 0; j < NSTATS; j++)
            if ((p0 >> j) & 1) s.boosts[A * NSTATS + j] = min(s.boosts[A * NSTATS + j] + p1, 6);
        return c * 2;
    }
    if (fam == 3) {
        if (s.status[D] == 0) { s.status[D] = p0; s.toxctr[D] = 1; }
        return c * 2;
    }
    if (fam == 8) { s.hp[D] -= s.level[A]; return c * 2; }
    int hits = fam == 5 ? p0 : 1, total = 0;
    for (int k = 0; k < hits; k++) { total += one_hit(s, lane, att, dfn, mi, c); c += 2; }
    s.hp[D] -= total;
    int fl = 0;
    if (fam == 6) s.hp[A] -= max(total * p0 / p1, 1);
    else if (fam == 7) s.hp[A] = min(s.hp[A] + total * p0 / p1, s.maxhp[A]);
    else if (fam == 1 || fam == 2 || fam == 9) {
        if (rand_n(draw(lane, s.gen[lane], c), 100) < p0 && s.hp[D] > 0) {
            if (fam == 1 && s.status[D] == 0) { s.status[D] = p1; s.toxctr[D] = 1; }
            else if (fam == 2) s.boosts[D * NSTATS + p1] = max(s.boosts[D * NSTATS + p1] - 1, -6);
            else if (fam == 9) fl = 1;
        }
        c += 1;
    }
    return c * 2 + fl;
}

__device__ void advance(St s, int lane) {
    int c = s.ctr[lane], g = s.gen[lane];
    int a0 = rand_n(draw(lane, g, c), 4), a1 = rand_n(draw(lane, g, c + 1), 4);
    c += 2;
    int sp0 = boosted(s.stats[(lane * 2) * NSTATS + 4], s.boosts[(lane * 2) * NSTATS + 4]);
    int sp1 = boosted(s.stats[(lane * 2 + 1) * NSTATS + 4], s.boosts[(lane * 2 + 1) * NSTATS + 4]);
    if (s.status[lane * 2] == 1) sp0 /= 4;
    if (s.status[lane * 2 + 1] == 1) sp1 /= 4;
    int first = 0;
    if (sp1 > sp0) first = 1;
    else if (sp1 == sp0) { first = rand_n(draw(lane, g, c), 2); c += 1; }
    int flinched = -1;
    for (int k = 0; k < 2; k++) {
        int att = k == 0 ? first : 1 - first, dfn = 1 - att;
        int A = lane * 2 + att, D = lane * 2 + dfn;
        if (s.hp[A] <= 0 || s.hp[D] <= 0 || flinched == att) continue;
        int st = s.status[A];
        if (st == 1) { if (rand_n(draw(lane, g, c), 4) < 1) { c += 1; continue; } c += 1; }
        else if (st == 5) {
            if (rand_n(draw(lane, g, c), 5) < 1) s.status[A] = 0;
            else { c += 1; continue; }
            c += 1;
        }
        int packed = use_move(s, lane, att, dfn, att == 1 ? a1 : a0, c);
        c = packed / 2;
        if (packed % 2 == 1) flinched = dfn;
    }
    for (int side = 0; side < 2; side++) {
        int b = lane * 2 + side, st = s.status[b];
        if (s.hp[b] > 0) {
            if (st == 4 || st == 2) s.hp[b] -= max(s.maxhp[b] / 8, 1);
            else if (st == 3) { s.hp[b] -= max(s.maxhp[b] * s.toxctr[b] / 16, 1); s.toxctr[b] += 1; }
        }
    }
    s.ctr[lane] = c;
    bool d0 = s.hp[lane * 2] <= 0, d1 = s.hp[lane * 2 + 1] <= 0;
    if (d0 || d1) {
        s.result[lane] = (d0 && d1) ? 3 : (d0 ? 2 : 1);
        init_lane(s, lane, g + 1);
    }
}

__global__ void k_init(St s, int n) { int i = blockIdx.x * blockDim.x + threadIdx.x; if (i < n) init_lane(s, i, 0); }
__global__ void k_step(St s, int n) { int i = blockIdx.x * blockDim.x + threadIdx.x; if (i < n) advance(s, i); }
__global__ void k_step_idx(St s, const int *idx, int n) {
    int i = blockIdx.x * blockDim.x + threadIdx.x; if (i < n) advance(s, idx[i]);
}
__global__ void k_fork(St s, const int *src, const int *dst, int n) {
    int i = blockIdx.x * blockDim.x + threadIdx.x; if (i >= n) return;
    int a = src[i], b = dst[i];
    for (int side = 0; side < 2; side++) {
        int A = a * 2 + side, B = b * 2 + side;
        s.hp[B] = s.hp[A]; s.maxhp[B] = s.maxhp[A]; s.status[B] = s.status[A];
        s.toxctr[B] = s.toxctr[A]; s.level[B] = s.level[A];
        for (int j = 0; j < NSTATS; j++) { s.stats[B * NSTATS + j] = s.stats[A * NSTATS + j]; s.boosts[B * NSTATS + j] = s.boosts[A * NSTATS + j]; }
        for (int j = 0; j < 2; j++) s.types[B * 2 + j] = s.types[A * 2 + j];
        for (int j = 0; j < 4; j++) s.mvs[B * 4 + j] = s.mvs[A * 4 + j];
    }
    s.ctr[b] = s.ctr[a]; s.gen[b] = s.gen[a]; s.result[b] = s.result[a];
}
__global__ void k_checksum(St s, unsigned long long *out, int n) {
    int lane = blockIdx.x * blockDim.x + threadIdx.x; if (lane >= n) return;
    unsigned long long h = 0xCBF29CE484222325ULL, P = 0x100000001B3ULL;
    for (int side = 0; side < 2; side++) {
        int b = lane * 2 + side;
        int words[4] = {s.hp[b], s.status[b], s.boosts[b * NSTATS + 0] + 8 * s.boosts[b * NSTATS + 3], s.toxctr[b]};
        for (int w = 0; w < 4; w++) h = (h ^ (unsigned long long)(uint32_t)words[w]) * P;
    }
    h = (h ^ (unsigned long long)(uint32_t)s.ctr[lane]) * P;
    h = (h ^ (unsigned long long)(uint32_t)s.gen[lane]) * P;
    out[lane] = h;
}
__global__ void k_reduce(const unsigned long long *in, unsigned long long *out, int n) {
    unsigned long long acc = 0;
    for (int i = 0; i < n; i++) acc += in[i];
    *out = acc;
}

static St alloc(int B) {
    St s;
    auto A = [&](int **p, size_t n) { CK(cudaMalloc(p, n * sizeof(int))); };
    A(&s.hp, B * 2); A(&s.maxhp, B * 2); A(&s.status, B * 2); A(&s.toxctr, B * 2); A(&s.level, B * 2);
    A(&s.stats, B * 2 * NSTATS); A(&s.boosts, B * 2 * NSTATS); A(&s.types, B * 2 * 2); A(&s.mvs, B * 2 * 4);
    A(&s.ctr, B); A(&s.gen, B); A(&s.result, B);
    return s;
}

int main(int argc, char **argv) {
    int B = argc > 1 ? atoi(argv[1]) : 4096;
    int iters = argc > 2 ? atoi(argv[2]) : 200;
    const char *mode = argc > 3 ? argv[3] : "dense";
    int TPB = 256, grid = (B + TPB - 1) / TPB, half = B / 2, ghalf = (half + TPB - 1) / TPB;

    St s = alloc(B);
    int *idx, *src, *dst;
    CK(cudaMalloc(&idx, B * sizeof(int))); CK(cudaMalloc(&src, half * sizeof(int))); CK(cudaMalloc(&dst, half * sizeof(int)));
    int *h = (int *)malloc(B * sizeof(int));
    for (int i = 0; i < B; i++) h[i] = (int)((uint32_t)i * 2654435761u & (uint32_t)(B - 1));
    CK(cudaMemcpy(idx, h, B * sizeof(int), cudaMemcpyHostToDevice));
    for (int i = 0; i < half; i++) h[i] = (i * 5 + 3) & (half - 1);
    CK(cudaMemcpy(src, h, half * sizeof(int), cudaMemcpyHostToDevice));
    for (int i = 0; i < half; i++) h[i] = half + i;
    CK(cudaMemcpy(dst, h, half * sizeof(int), cudaMemcpyHostToDevice));

    k_init<<<grid, TPB>>>(s, B);
    CK(cudaDeviceSynchronize());

    auto iteration = [&](cudaStream_t st) {
        if (!strcmp(mode, "dense")) k_step<<<grid, TPB, 0, st>>>(s, B);
        else { k_fork<<<ghalf, TPB, 0, st>>>(s, src, dst, half); k_step_idx<<<grid, TPB, 0, st>>>(s, idx, B); }
    };
    cudaStream_t stream; CK(cudaStreamCreate(&stream));
    bool use_graph = !strcmp(mode, "graph");
    cudaGraphExec_t exec = nullptr;
    for (int i = 0; i < 20; i++) iteration(stream);      // warm up
    CK(cudaStreamSynchronize(stream));
    k_init<<<grid, TPB>>>(s, B);                        // reset so the checksum covers exactly `iters`
    CK(cudaDeviceSynchronize());
    if (use_graph) {
        cudaGraph_t g;
        CK(cudaStreamBeginCapture(stream, cudaStreamCaptureModeGlobal));
        iteration(stream);
        CK(cudaStreamEndCapture(stream, &g));
        CK(cudaGraphInstantiate(&exec, g, nullptr, nullptr, 0));
    }
    cudaEvent_t t0, t1; CK(cudaEventCreate(&t0)); CK(cudaEventCreate(&t1));
    CK(cudaEventRecord(t0, stream));
    for (int i = 0; i < iters; i++) { if (use_graph) CK(cudaGraphLaunch(exec, stream)); else iteration(stream); }
    CK(cudaEventRecord(t1, stream));
    CK(cudaStreamSynchronize(stream));
    float ms = 0; CK(cudaEventElapsedTime(&ms, t0, t1));

    unsigned long long *hashes, *total, hsum;
    CK(cudaMalloc(&hashes, B * sizeof(unsigned long long))); CK(cudaMalloc(&total, sizeof(unsigned long long)));
    k_checksum<<<grid, TPB>>>(s, hashes, B);
    k_reduce<<<1, 1>>>(hashes, total, B);
    CK(cudaMemcpy(&hsum, total, sizeof(unsigned long long), cudaMemcpyDeviceToHost));
    printf("{\"impl\":\"cuda\",\"mode\":\"%s\",\"batch\":%d,\"iters\":%d,\"ms\":%.4f,\"checksum\":\"%016llx\"}\n",
           mode, B, iters, ms, hsum);
    return 0;
}
